sourceCallsites.argumentsSignature:
token, {
        requestType: "agent",
        agentName: agentName.trim(),
        adapterType,
        capabilities: capabilities.trim() || null,
      }

input.receipt.companyId, input.memberId, {
        reassignment,
        routineResponsibleUserId: input.routineTarget.startsWith("user:")
          ? input.routineTarget.slice("user:".length)
          : null,
      }

companyId, {
        allowedJoinTypes: "agent",
        humanRole: null,
        agentMessage: message.trim() || null,
      }

input.receipt.companyId, input.memberId, {
        membershipRole: input.membershipRole,
        status: input.status,
      }

captured.companyId, captured.userId, updating!.id, {
                  ...input(),
                  expectedVersion: updating!.version,
                  approveMaterialChange: material,
                  reason,
                }

createdCompanyId, {
        // The name is optional; an agent that reaches here without one is
        // named for the job it was hired to do rather than left blank.
        name: hireName,
        appearance: agentAppearance,
        role: agentRole,
        adapterType,
        adapterConfig: hireAdapterConfig,
        ...(shouldApplyStoredClaudeLogin ? { applyStoredClaudeLogin: true } : {}),
        // The server owns what the first agent is told now: this marker seeds
        // the chief-of-staff persona over the agent's entry instruction file.
        // The wizard no longer composes or overwrites it.
        onboardingFirstAgent: true,
        runtimeConfig: { ...buildNewAgentRuntimeConfig(), ...(managedBinding ? { aiConnection: managedBinding } : {}) }
      }

companyId, {
        environmentId,
        aiConnection,
        // When the owner already has a stored token, the login rotates it under
        // the captured version, so a replacement login never conflicts with an
        // existing value. Without a stored token the login is a first write.
        ...(storedToken && !aiConnection
          ? {
              overwrite: {
                expectedSecretId: storedToken.secretId,
                expectedLatestVersion: storedToken.latestVersion,
              },
            }
          : {}),
      }

createdCompanyId, adapterType, {
          adapterConfig: adapterConfigOverride ?? buildAdapterConfig(),
          ...(managedBindingForStep() ? { aiConnection: managedBindingForStep() } : {}),
          environmentId,
        }

agentId, {
          ...permissions,
          canCreateAgents: permissions.canCreateAgents ?? false,
          canCreateSkills: permissions.canCreateSkills ?? true,
          canAssignTasks: agentDetail.data?.access?.canAssignTasks ?? false,
        }, companyId

run.agentId, {
        source: "on_demand",
        triggerDetail: "manual",
        reason: "resume_process_lost_run",
        payload: resumePayload,
      }, run.companyId

issueAssigneeAgentIdForResume, {
              source: "assignment",
              reason: "Assignee resumed from the task page",
              payload: {
                issueId: issueIdForResume,
                mutation: "assignee_resumed",
              },
            }, issueCompanyIdForResume ?? undefined

restartIssue.assigneeAgentId, {
              source: "assignment",
              triggerDetail: "manual",
              reason: "recent_task_restart",
              payload: { issueId: restartIssue.id },
            }, restartIssue.companyId

restartIssue.assigneeAgentId, {
              source: "assignment",
              triggerDetail: "manual",
              reason: "recent_task_restart_retry",
              payload: { issueId: restartIssue.id },
            }, restartIssue.companyId

companyId, current.artifact.id, {
        expectedStatus: current.artifact.status, expectedLatestVersionId: current.latestVersion.id, status: action,
      }

companyId, {
        scopeType: input.scopeType,
        scopeId: input.scopeId,
        amount: input.amount,
        windowKind: input.windowKind,
      }

resolvedCompanyId!, {
        scopeType: "project",
        scopeId: project?.id ?? routeProjectRef,
        amount,
        windowKind: "lifetime",
      }

companyId, definition.key, {
        adapterType,
        adapterConfig,
        ...(budgetMonthlyCents !== undefined ? { budgetMonthlyCents } : {}),
      }

endpointId, input.item.id, input.action, input.item.fileTransfer
            ? {
                phase: input.item.fileTransfer.phase,
                version: input.item.fileTransfer.version,
              }
            : undefined

endpointId, provider === "imessage-photon" ? {
      action,
      ...(values?.projectSecret ? { credentials: { projectSecret: values.projectSecret } } : {}),
      ...(values?.projectId && values.allocation === "shared" ? { photon: { allocation: "shared" as const, projectId: values.projectId } } : values?.projectId && values?.lineId ? { photon: { allocation: "dedicated" as const, projectId: values.projectId, lineId: values.lineId } } : {}),
        } : { action, credentials: values }

endpoint.id, {
                  action: "reconnect",
                  ...(credentials.privateKey
                    ? {
                        credentials: {
                          appId: credentials.appId || endpoint.botExternalId!,
                          privateKey: credentials.privateKey,
                        },
                      }
                    : {}),
                }

endpoint.id, resources.map((resource) => ({
                  id: resource.id,
                  enabled: resource.enabled,
                }))

selectedCompanyId!, {
        include: { company: true, agents: true, projects: true, issues: withIssues, skills: includeSkills },
        sidebarOrder,
      }, { signal }

companyId, {
      projectId: project.id,
      workspaceId,
      path: folderPath,
    }

companyId, skillId, buildCreateRunRequest({
        agentId: selectedAgentId!,
        inputId: adHocMode ? null : selectedInput?.id ?? null,
        content: adHocMode ? adHocContent : selectedInput ? null : adHocContent,
        templateId: resolution.selection,
      })

selectedCompanyId!, {
        catalogSkillId: payload.catalogSkillId,
        slug: payload.slug,
        force: payload.force,
      }

companyId, {
        projectIds: [selectedProject.id],
        mode: "preview",
        selection: [{ workspaceId, path: skillPath }],
      }

options.target, {
        baseRevisionId: options.baseRevisionId,
        baseRevisionNumber: options.baseRevisionNumber,
        selector: options.pendingAnchor.selector,
        body,
      }

captured.companyId, captured.userId, {
                  userId: memberId,
                  subject,
                  manageMembershipLifecycle: manageLifecycle,
                  reason,
                }
